// ─────────────────────────────────────────────────────────────────────────────
// File monitor exclusions (dlp_agent::interception::{FileAction, InterceptionEngine})
// ─────────────────────────────────────────────────────────────────────────────

mod file_monitor_exclusion_tests {
    use dlp_agent::config::AgentConfig;
    use dlp_agent::interception::{FileAction, InterceptionEngine};

    /// Default config constructs an engine without panicking and with the
    /// stop flag unset.
    #[test]
    fn test_interception_engine_default_constructs() {
        let engine = InterceptionEngine::default();
        // Drop to trigger the stop flag -- must not panic.
        drop(engine);
    }

    /// A config with a user-supplied exclusion list round-trips into the
    /// engine without mutating the stored list. We verify via the config
    /// clone that exclusions are preserved verbatim (exclusion matching is
    /// case-insensitive at match time, not at store time).
    #[test]
    fn test_engine_with_config_preserves_excluded_paths() {
        let cfg = AgentConfig {
            excluded_paths: vec![r"C:\BuildOutput\".to_string(), r"D:\MyCache\".to_string()],
            ..Default::default()
        };
        let engine = InterceptionEngine::with_config(cfg.clone()).expect("engine construction");
        // The config was moved into the engine; use the clone we kept and
        // assert it matches what we passed in.
        assert_eq!(
            cfg.excluded_paths,
            vec![r"C:\BuildOutput\".to_string(), r"D:\MyCache\".to_string()],
        );
        drop(engine);
    }

    /// `FileAction::path()` returns the target path for every variant. The
    /// exclusion matcher consumes this string, so the return contract is
    /// part of the file-monitor exclusion surface.
    #[test]
    fn test_file_action_path_for_all_variants() {
        let created = FileAction::Created {
            path: r"C:\Data\a.txt".to_string(),
            process_id: 1,
            related_process_id: 0,
        };
        assert_eq!(created.path(), r"C:\Data\a.txt");

        let written = FileAction::Written {
            path: r"C:\Data\b.txt".to_string(),
            process_id: 2,
            related_process_id: 0,
            byte_count: 100,
        };
        assert_eq!(written.path(), r"C:\Data\b.txt");

        let deleted = FileAction::Deleted {
            path: r"C:\Data\c.txt".to_string(),
            process_id: 3,
            related_process_id: 0,
        };
        assert_eq!(deleted.path(), r"C:\Data\c.txt");

        let read = FileAction::Read {
            path: r"C:\Data\d.txt".to_string(),
            process_id: 4,
            related_process_id: 0,
            byte_count: 200,
        };
        assert_eq!(read.path(), r"C:\Data\d.txt");

        // Moved uses the new path.
        let moved = FileAction::Moved {
            old_path: r"C:\Data\old.txt".to_string(),
            new_path: r"C:\Data\new.txt".to_string(),
            process_id: 5,
            related_process_id: 0,
        };
        assert_eq!(moved.path(), r"C:\Data\new.txt");
    }

    /// Empty exclusion list is a valid, non-panicking config -- the engine
    /// accepts it and `FileAction::path()` still works on every variant.
    #[test]
    fn test_engine_with_empty_exclusion_list() {
        // Default already has excluded_paths = vec![], so no fields need overriding.
        let cfg = AgentConfig::default();
        let _engine = InterceptionEngine::with_config(cfg).expect("engine construction");
    }

    /// Multiple user exclusions in the config are accepted without being
    /// coalesced or silently de-duplicated -- every entry survives the
    /// `with_config` constructor.
    #[test]
    fn test_engine_with_many_user_exclusions() {
        let cfg = AgentConfig {
            excluded_paths: vec![
                r"C:\cache1\".to_string(),
                r"C:\cache2\".to_string(),
                r"C:\cache3\".to_string(),
            ],
            ..Default::default()
        };
        assert_eq!(cfg.excluded_paths.len(), 3);
        let _engine = InterceptionEngine::with_config(cfg).expect("engine construction");
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// DLP TC tests — file operations (TC-01, 10, 11, 12, 13, 14, 60, 61, 62, 70, 71, 72)
// ─────────────────────────────────────────────────────────────────────────────

mod file_ops_tc {
    use dlp_agent::interception::PolicyMapper;
    use dlp_common::Classification;

    /// TC-01: Internal file open → ALLOW
    #[test]
    fn test_tc_01_internal_file_open_allowed() {
        let path = r"C:\Data\report.xlsx";
        let cls = PolicyMapper::provisional_classification(path);
        assert_eq!(cls, Classification::T2);
        // T2 is not sensitive — open is allowed by ABAC default.
        assert!(!cls.is_sensitive());
    }

    /// TC-02: Confidential file open (unauthorized) → DENY + log
    #[test]
    fn test_tc_02_confidential_file_open_denied_logged() {
        let path = r"C:\Confidential\doc.docx";
        let cls = PolicyMapper::provisional_classification(path);
        assert_eq!(cls, Classification::T3);
        // T3 is sensitive — ABAC should return DENY without explicit allow policy.
        assert!(cls.is_sensitive());
    }

    /// TC-03: Restricted file open → DENY + alert
    #[test]
    fn test_tc_03_restricted_file_open_denied_alert() {
        let path = r"C:\Restricted\secret.xlsx";
        let cls = PolicyMapper::provisional_classification(path);
        assert_eq!(cls, Classification::T4);
        // T4 is always fail-closed — DENY regardless of ABAC policy.
        assert!(cls.is_sensitive());
    }

    /// TC-10: Copy Internal file within system → ALLOW
    #[test]
    fn test_tc_10_copy_internal_within_system_allowed() {
        let src = PolicyMapper::provisional_classification(r"C:\Data\folder_A\report.xlsx");
        let dst = PolicyMapper::provisional_classification(r"C:\Data\folder_B\copy.xlsx");
        assert_eq!(src, Classification::T2);
        assert_eq!(dst, Classification::T2);
        assert!(!src.is_sensitive());
    }

    /// TC-11: Copy Confidential to Internal folder → DENY + alert
    #[test]
    fn test_tc_11_copy_confidential_to_internal_blocked_alert() {
        let src = PolicyMapper::provisional_classification(r"C:\Confidential\finance.xlsx");
        let dst = PolicyMapper::provisional_classification(r"C:\Data\internal_folder\copy.xlsx");
        assert_eq!(src, Classification::T3);
        assert_eq!(dst, Classification::T2);
        // Confidential (T3) being copied to Internal (T2) folder is a downgrade.
        assert!(src > dst);
    }

    /// TC-12: Copy Restricted to Public folder → DENY + log + alert
    #[test]
    fn test_tc_12_copy_restricted_to_public_blocked() {
        let src = PolicyMapper::provisional_classification(r"C:\Restricted\secret.xlsx");
        let dst = PolicyMapper::provisional_classification(r"C:\Public\upload\file.txt");
        assert_eq!(src, Classification::T4);
        assert_eq!(dst, Classification::T1);
        assert!(src > dst);
    }

    /// TC-13: Move Confidential within same level → ALLOW
    #[test]
    fn test_tc_13_move_confidential_same_level_allowed() {
        let src = PolicyMapper::provisional_classification(r"C:\Confidential\folder_A\doc.docx");
        let dst = PolicyMapper::provisional_classification(r"C:\Confidential\folder_B\doc.docx");
        assert_eq!(src, Classification::T3);
        assert_eq!(dst, Classification::T3);
        assert_eq!(src, dst);
    }

    /// TC-14: Copy Confidential to USB → DENY + log
    #[test]
    #[cfg(windows)]
    fn test_tc_14_copy_confidential_to_usb_blocked_log() {
        use dlp_agent::detection::UsbDetector;

        let cls = PolicyMapper::provisional_classification(r"C:\Confidential\report.pdf");
        assert_eq!(cls, Classification::T3);
        assert!(cls.is_sensitive());
        // On a non-USB path, should_block_write returns false — classification
        // is T3 (sensitive) but the destination is not a blocked USB drive.
        // TC-14 E2E in integration.rs covers the full pipeline with seeded blocked drive.
        let detector = UsbDetector::new();
