    fn try_manager() -> Option<WfpManager> {
        match WfpManager::new() {
            Ok(m) => Some(m),
            Err(WfpError::EngineUnavailable(code)) => {
                eprintln!("Skipping WFP test: engine unavailable (code {code})");
                None
